    /** {@code AdminRequestCallPacket}: id 7, client to server, normal priority, TCP. */
    public record AdminRequest(int other, AdminAction action, Object params) implements Packet{
        public static final int ID = 7;

        @Override
        public int packetId(){
            return ID;
        }

        @Override
        public void write(Writes write, boolean fromServer, WireContext context){
            write.i(other);
            write.b(action.ordinal());
            WireObjects.writeObjectSafe(write, params);
        }

        public static AdminRequest read(Reads read, boolean fromServer, WireContext context){
            int other = Codecs.readEntity(read, EntityClasses::isPlayer, "Player", context);
            AdminAction action = AdminAction.of(read.b());
            Object params = WireObjects.readObjectSafe(read, context);
            return new AdminRequest(other, action, params);
        }
    }

